fn registry_table(entries: &[(&str, Ecosystem)]) -> BTreeMap<RegistryKey, RegistryConfig> {
    entries
        .iter()
        .map(|(name, kind)| {
            (
                RegistryKey((*name).to_owned()),
                RegistryConfig {
                    kind: *kind,
                    url: None,
                    publish_url: None,
                    confirm_timeout: None,
                    publish_timeout: None,
                },
            )
        })
        .collect()
}

