        (RegistryKey::CRATES_IO, Ecosystem::Cargo),
        ("my.reg", Ecosystem::Cargo),
    ]);
    assert!(
        parse_publish_target("my.reg", &registries).is_none(),
        "a name cargo cannot take as `--registry` fails at load"
