/// A cargo registry has no endpoint override: cargo takes its destination from `.cargo/config.toml`, so a `url`

fn load_error(toml: &str) -> (String, String) {
    let tmp = tempfile::tempdir().expect("tempdir");
    fs::write(tmp.path().join("callisto.toml"), toml).expect("write callisto.toml");
    let error = load(tmp.path()).expect_err(toml);
    let code = miette::Diagnostic::code(&error).map(|code| code.to_string()).unwrap_or_default();
    let help = miette::Diagnostic::help(&error).map(|help| help.to_string()).unwrap_or_default();
    (code, format!("{error}\n{help}"))
}

