    if parse_publish_target(&raw, &BTreeMap::new()).is_some() {
        return Err(unknown(format!(
            "`[registries.{raw}]`: `{raw}` is a publish-to word, not a registry; rename it"
        )));
    }
    RegistryName::parse(raw.clone()).map(RegistryKey::from).map_err(|_| {
        unknown(format!(
            "`[registries.{raw}]`: a registry name is letters, digits, `-` and `_`, and does not start with `-`"
        ))
    })
}

